 final MainActivity a;final ExecutorService worker=Executors.newSingleThreadExecutor();AlertDialog dialog;EditText host,user,pass,domain,port,share,sub,profileName;TextView status,chosen;Button find,discover,save;LinearLayout advanced;CheckBox custom;boolean manual=false,selecting=false,disposed=false;String selected="";int request=0;ShareBrowser.Job sharesJob;PcDiscovery.Job discoveryJob;Runnable timeout;
 ConnectionDialog(MainActivity activity){a=activity;}
