  form.addView(a.text("PC 찾기는 약 8초 동안 현재 Wi-Fi만 확인합니다. 발견된 PC에는 자동 로그인하지 않습니다.",13,a.MUTED),a.lp(-1,62));
  user=a.field(form,"Windows 사용자명",saved.user,false);pass=a.field(form,"암호 (Windows 로그인 PIN 아님)",saved.password,true);domain=a.field(form,"도메인 / PC 이름 (선택)",saved.domain,false);
  find=a.button("이 PC의 공유 폴더 찾기",true,this::lookup);form.addView(find,a.lp(-1,50));status=a.text("주소와 계정을 입력한 뒤 공유 폴더를 찾으세요.",14,a.MUTED);status.setMinHeight(a.dp(62));form.addView(status,a.lp(-1,-2));
  chosen=a.text("선택한 공유 폴더 없음",16,a.INK);chosen.setTypeface(null,Typeface.BOLD);form.addView(chosen,a.lp(-1,48));
  custom=new CheckBox(a);custom.setText("고급: 공유 이름 직접 입력 / 하위 경로 / 포트");custom.setTextSize(13);form.addView(custom,a.lp(-1,52));advanced=a.column();share=a.field(advanced,"공유 이름",saved.share,false);sub=a.field(advanced,"공유 안의 하위 경로 (선택)",saved.root,false);port=a.field(advanced,"SMB 포트",String.valueOf(saved.port),false);port.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);form.addView(advanced);advanced.setVisibility(View.GONE);
  custom.setOnCheckedChangeListener((v,on)->{cancel();manual=on;selected="";chosen.setText(on?"공유 이름 직접 입력 사용":"선택한 공유 폴더 없음");advanced.setVisibility(on?View.VISIBLE:View.GONE);});
  profileName=a.field(form,"연결 이름 (선택)","",false);
