  TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!selecting){cancel();selected="";if(chosen!=null)chosen.setText(manual?"공유 이름 직접 입력 사용":"선택한 공유 폴더 없음");}}public void afterTextChanged(Editable e){}};
