 void fill(Config cfg,String name){cancel();selecting=true;boolean extra=!cfg.root.isEmpty()||cfg.port!=445;custom.setChecked(extra);host.setText(cfg.host);user.setText(cfg.user);pass.setText(cfg.password);domain.setText(cfg.domain);port.setText(String.valueOf(cfg.port));sub.setText(cfg.root);share.setText(cfg.share);profileName.setText(name);selected=cfg.share;manual=extra;chosen.setText("선택한 공유: "+selected);advanced.setVisibility(extra?View.VISIBLE:View.GONE);selecting=false;status.setText("저장된 값을 불러왔습니다. 확인 후 연결하세요. 아직 로그인하지 않았습니다.");}
 void saveProfile(){try{new SavedConnections(a).save(profileName.getText().toString(),input(true));status.setText("이 기기에 암호화해 저장했습니다. 불러오기에서 다시 선택할 수 있습니다.");}catch(Exception e){status.setText("연결 이름·주소·계정·공유를 확인해 주세요. 최대 20개이며 안전한 저장에 실패하면 저장하지 않습니다.");}}
 void loadProfiles(){cancel();try{List<SavedConnections.Profile> profiles=new SavedConnections(a).all();if(profiles.isEmpty()){status.setText("저장된 연결 목록이 없습니다. 현재 입력을 저장해 주세요. 마지막 연결 값은 자동으로 채워집니다.");return;}String[] names=new String[profiles.size()];for(int i=0;i<names.length;i++)names[i]=profiles.get(i).name;final int[] choice={0};AlertDialog picker=new AlertDialog.Builder(a).setTitle("이 기기의 저장된 연결").setSingleChoiceItems(names,0,(d,w)->choice[0]=w).setPositiveButton("불러오기",(d,w)->{SavedConnections.Profile p=profiles.get(choice[0]);fill(p.config,p.name);}).setNeutralButton("삭제",(d,w)->{SavedConnections.Profile p=profiles.get(choice[0]);new AlertDialog.Builder(a).setTitle("저장된 연결 삭제").setMessage(p.name+"을 목록에서 삭제할까요? 현재 연결 정보는 별도로 유지됩니다.").setPositiveButton("삭제",(dd,ww)->{try{new SavedConnections(a).remove(p.id);status.setText("연결 목록에서 삭제했습니다.");}catch(Exception e){status.setText("삭제하지 못했습니다.");}}).setNegativeButton("취소",null).show();}).setNegativeButton("취소",null).create();picker.show();picker.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);}catch(Exception e){status.setText("암호화된 연결 목록을 열지 못했습니다. 현재 입력값을 확인해 주세요.");}}
 Config input(boolean withShare){Config cfg=new Config();cfg.host=host.getText().toString().trim();cfg.user=user.getText().toString().trim();cfg.password=pass.getText().toString();cfg.domain=domain.getText().toString().trim();try{cfg.port=Integer.parseInt(port.getText().toString());}catch(Exception e){throw new IllegalArgumentException("포트를 숫자로 입력해 주세요");}if(cfg.host.isEmpty()||cfg.host.contains("://")||cfg.host.contains("/")||cfg.host.contains("\\")||cfg.host.chars().anyMatch(c->c<=32)||cfg.port<1||cfg.port>65535)throw new IllegalArgumentException("PC 주소/IP와 포트를 확인해 주세요");if(cfg.user.isEmpty()||cfg.password.isEmpty())throw new IllegalArgumentException("먼저 Windows 사용자명과 계정 암호를 입력해 주세요");cfg.share=manual?share.getText().toString().trim():selected;cfg.root=com.picviewer.core.Paths.normalize(sub.getText().toString());if(withShare&&(cfg.share.isEmpty()||cfg.share.contains("/")||cfg.share.contains("\\")))throw new IllegalArgumentException("공유 폴더를 찾고 선택하거나 고급에서 이름을 입력해 주세요");return cfg;}
 void save(){try{Config cfg=input(true);cancel();a.activate(cfg);dialog.dismiss();a.scan(true);}catch(IllegalArgumentException e){status.setText(e.getMessage());}catch(Exception e){status.setText("연결 정보를 안전하게 저장하지 못했습니다. 다시 확인해 주세요.");}}
 void busy(boolean on){if(find!=null)find.setEnabled(!on);if(discover!=null)discover.setEnabled(!on);if(save!=null)save.setEnabled(!on);}
 void cancel(){request++;if(timeout!=null)a.ui.removeCallbacks(timeout);if(sharesJob!=null)sharesJob.close();if(discoveryJob!=null)discoveryJob.close();sharesJob=null;discoveryJob=null;busy(false);}
 int begin(){cancel();busy(true);int token=request;timeout=()->{if(token!=request||disposed)return;cancel();status.setText("응답 확인 시간이 지났습니다. 직접 IP/공유 이름 입력을 사용할 수 있습니다.");};a.ui.postDelayed(timeout,30000);return token;}
 boolean current(int token){return !disposed&&dialog!=null&&dialog.isShowing()&&token==request;}
 void finish(){if(timeout!=null)a.ui.removeCallbacks(timeout);busy(false);}
 void lookup(){final Config cfg;try{cfg=input(false);}catch(IllegalArgumentException e){status.setText(e.getMessage());return;}int token=begin();ShareBrowser.Job job=new ShareBrowser.Job();sharesJob=job;status.setText("선택한 PC에 로그인해 공유 목록을 확인합니다…");worker.execute(()->{try{List<String> names=ShareBrowser.find(cfg,job);a.ui.post(()->{if(!current(token))return;finish();showShares(names);});}catch(Exception e){String kind=SmbSource.kind(e);a.ui.post(()->{if(!current(token))return;finish();status.setText(kind.equals("AUTH")?"계정/암호를 확인해 주세요. 반복 로그인은 하지 않습니다.":kind.equals("DENIED")?"공유 목록 조회 권한이 없습니다. 고급에서 공유 이름을 직접 입력할 수 있습니다.":"공유 목록을 가져오지 못했습니다. PC 주소·연결·서버 설정을 확인하거나 고급 직접 입력을 사용하세요.");});}finally{job.close();}});}
 void showShares(List<String> names){if(names.isEmpty()){status.setText("선택할 일반 디스크 공유가 없습니다. 숨김 공유는 고급 직접 입력을 사용하세요.");return;}status.setText("공유 "+names.size()+"개 · 선택 후 저장 시 실제 폴더 읽기를 확인합니다.");new AlertDialog.Builder(a).setTitle("공유 폴더 선택").setItems(names.toArray(new String[0]),(d,which)->{custom.setChecked(false);selected=names.get(which);manual=false;selecting=true;sub.setText("");share.setText(selected);selecting=false;chosen.setText("선택한 공유: "+selected);}).setNegativeButton("취소",null).show();}
 void discover(){int token=begin();PcDiscovery.Job job=new PcDiscovery.Job();discoveryJob=job;status.setText("현재 Wi-Fi에서 PC를 찾습니다… (약 8초)");worker.execute(()->{try{List<String> addresses=PcDiscovery.find(a,job);a.ui.post(()->{if(!current(token))return;finish();showComputers(addresses);});}catch(Exception e){a.ui.post(()->{if(!current(token))return;finish();status.setText("PC 검색을 마치지 못했습니다. IPv4 Wi-Fi·Windows 네트워크 검색·방화벽을 확인하거나 IP를 직접 입력하세요.");});}finally{job.close();}});}
 void showComputers(List<String> addresses){if(addresses.isEmpty()){status.setText("검색된 PC가 없습니다. PC가 없다는 뜻은 아닙니다. 주소/IP 직접 입력을 사용하세요.");return;}status.setText("PC 후보 "+addresses.size()+"개 · 내 PC의 IP인지 확인해 선택하세요. 발견은 신원 확인이 아닙니다.");String[] labels=new String[addresses.size()];for(int i=0;i<labels.length;i++)labels[i]=addresses.get(i)+"  ·  WS-Discovery PC 후보";new AlertDialog.Builder(a).setTitle("PC 주소 선택").setMessage("내 PC인지 확인한 뒤 선택하세요. 선택만으로 로그인하지 않습니다.").setPositiveButton("목록 보기",(d,w)->new AlertDialog.Builder(a).setTitle("PC 후보").setItems(labels,(dd,which)->{host.setText(addresses.get(which));status.setText("주소를 넣었습니다. 계정을 확인한 뒤 공유 폴더 찾기를 누르세요.");}).setNegativeButton("취소",null).show()).setNegativeButton("취소",null).show();}
